parameters.jsCode:
// Process the input items
const inputItem = items[0].json.output;

// Extract industry overview
const industryOverview = inputItem.industryOverview;

// Format big players data
const formattedPlayers = inputItem.currentBigPlayers.map((player, index) => {
  // Format top selling products
  const formattedProducts = player.topSellingProducts.map(product => 
    `-Product Name: ${product.productName} \n -- ${product.productDescription}`
  ).join('\n\n');

  // Format player information
  return `${index + 1}. Brand: ${player.brandName},\n\n` +
         `Year Founded: ${player.yearFounded},\n\n` +
         `Location Founded: ${player.locationFounded},\n\n` +
         `Product Types: ${player.productTypes}.\n\n` +
         `Top Selling Products: \n\n${formattedProducts}`;
});

// Create output structure
return [{
  json: {
    industryOverview: industryOverview,
    industryBigPlayer: formattedPlayers.join('\n\n')
  }
}];

