const inputData = items[0].json.output;

// Format industry challenges
const industryChallenges = inputData.industryChallenges.map((challenge, index) => {
  return `${index + 1}. ${challenge.keyPoint}\n - ${challenge.description}`;
}).join('\n\n');

// Format market challenges
const marketChallenges = inputData.marketChallenges.map((challenge, index) => {
  return `${index + 1}. ${challenge.keyPoint}\n - ${challenge.description}`;
}).join('\n\n');

// Return both in a single item
return [{
  json: {
    industryChallenges: industryChallenges,
    marketChallenges: marketChallenges
  }
}];

